-- 无尽模式下的 TrackMapReader

---@class TrackMapReaderInfinity
local TrackMapReaderInfinity = Class("TrackMapReaderInfinity")


---@type ParkourGameUtil
local ParkourGameUtil = import("Game.Activity.ParkourGame.ParkourGameUtil")


local Vector3 = CS.UnityEngine.Vector3
local Mathf = CS.UnityEngine.Mathf

---@type Queue
local Queue = import("Game.DreamSpace.Tools.Queue")


---@type ParkourGameMgr
local Mgr = import("Game.Activity.ParkourGame.ParkourGameMgr"):GetInstance()


-- ======================================================

---@param factory_ ParkourFactory
function TrackMapReaderInfinity:__init( factory_,mapVos_ )

    self.factory = factory_
    self.width = ParkourGameUtil.InteractionTrackWidth -- 16, 一屏幕宽度(米)

    self.mapVos = mapVos_ -- MiniWorldInfiniteMapVo row[] 
    self.trackMaps = {}


    for i=1, #self.mapVos do 
        local vo = self.mapVos[i]
        local mapName = checkString(vo.prefabId)
        assert( string.isEmpty(mapName) == false )

        local trackMap = import("Game.Activity.ParkourGame.MainGame.Data."..mapName) -- !! "Level1" 这种 lua 数据文件
        table.sort(trackMap.Map, function(a,b)
            return a.x < b.x
        end)
        ---
        local mapLen = trackMap.Map[#trackMap.Map].x
        local pageNum = Mathf.Max( 1, Mathf.Ceil(mapLen/self.width)) -- 关卡一共有 几页, 一页等于 1 trackSegment
        --local pageNum = Mathf.Max( 1, Mathf.Floor(mapLen/self.width))
        ---
        trackMap.mapName = mapName
        trackMap.mapLen = mapLen
        trackMap.pageNum = pageNum
        ---
        table.insert( self.trackMaps, trackMap )
    end

    self.currentMapFirstPageIdx0Based = 0 -- 始终在累加

    -- map idx 队列; 
    self.mapIdxOrderList = {} -- 每次都对它进行洗牌
    ---@type Queue
    self._mapIdxQueue = Queue.New(10)
    for i=1, #self.trackMaps do 
        self._mapIdxQueue:AddLast(i)
        table.insert(self.mapIdxOrderList, i)
    end 
end




---读取数据,为这个轨道片段生成交互物品
---@param trackSegment_ InteractionTrackSegment
function TrackMapReaderInfinity:GenerateSegmentItems(trackSegment_)

    local currentMapIdx = self._mapIdxQueue:PeekFirst()
    local currentTrackMap = self.trackMaps[currentMapIdx]

    local Idx1Based = trackSegment_.segmentIndex - self.currentMapFirstPageIdx0Based -- 1 based; segment idx
    if Idx1Based > currentTrackMap.pageNum then 
        -- 说明需要 进入下一个 tackMap 了:

        self.currentMapFirstPageIdx0Based = self.currentMapFirstPageIdx0Based + currentTrackMap.pageNum

        self._mapIdxQueue:RemoveFirst()
        if self._mapIdxQueue:Count() == 0 then 
            -- 洗牌:
            while true do 
                table.shuffle(self.mapIdxOrderList)
                if self.mapIdxOrderList[1] ~= currentMapIdx then 
                    break
                end 
            end 
            
            local shuffleRet = "洗牌结果: "
            for i=1,#self.mapIdxOrderList do 
                shuffleRet = shuffleRet .. tostring(self.mapIdxOrderList[i]) .. ", "
                self._mapIdxQueue:AddLast( self.mapIdxOrderList[i] )
            end 
            print(shuffleRet)
        end 
        ---
        currentMapIdx = self._mapIdxQueue:PeekFirst()
        currentTrackMap = self.trackMaps[currentMapIdx]
        print("进入新的 trackMap: " .. tostring(currentMapIdx))

        -- 更换 中景 数据:
        if isNotNull(Mgr.gameRunner.tracks[2]) and isNotNull(Mgr.gameRunner.tracks[2].othDatas) and isNotNull(Mgr.gameRunner.tracks[2].othDatas.prefabPaths) then 
            Mgr.gameRunner.tracks[2].othDatas.prefabPaths = self:MiddlePrefabs()
        else 
            printError("异常, 放弃更换 track2 图集数据" )
        end 

        -- 更换 boss 数据:  
        if isNotNull(Mgr.boss) then 
            Mgr.boss:ChangeCrowData( self:CrowData() )
        else 
            printError("异常, 放弃更换 boss 数据" )
        end 

        ---
        Idx1Based = trackSegment_.segmentIndex - self.currentMapFirstPageIdx0Based
        assert( Idx1Based <= currentTrackMap.pageNum )
    end 

    -- trackSegment pos.x 位于 segment 的正中间:
    local startPos = Mathf.Max(Idx1Based-1,0) * self.width - self.width/2
    local endPos = startPos + self.width

    local curIndex = 1
    
    while curIndex <= #currentTrackMap.Map do
        local node = currentTrackMap.Map[curIndex]
        -- !!! 通过这个 magicNumber 来解决两张 map 之间的接缝问题; 即:让新的 page 在前面多生成一些元素
        if node.x < (startPos - 3) then
            curIndex = curIndex + 1
        elseif node.x >= endPos then
            break
        else
            local localX = node.x - startPos - self.width/2
            local localY = node.y
            self.factory:GenerateTrackItem(currentTrackMap.prefabPath[node.path],function(trackItem)
                trackSegment_:AddItem(trackItem, localX, localY)
            end)
            curIndex = curIndex + 1
        end
    end
end



function TrackMapReaderInfinity:ImgPaths()
    local currentTrackMap = self.trackMaps[self._mapIdxQueue:PeekFirst()]
    return checkTable(currentTrackMap.BackImgs)
end


function TrackMapReaderInfinity:MiddlePrefabs()
    local currentTrackMap = self.trackMaps[self._mapIdxQueue:PeekFirst()]
    return checkTable(currentTrackMap.MiddlePrefabs)
end

---@return CrowData
function TrackMapReaderInfinity:CrowData()
    local currentTrackMap = self.trackMaps[self._mapIdxQueue:PeekFirst()]
    return checkTable(currentTrackMap.CrowData)
end


-- 本关卡的长度
function TrackMapReaderInfinity:GetLevelLength()
    printError("无限模式中, 本函数不该被调用到 ...")
end



function TrackMapReaderInfinity:Reset()
    printError("Reset 施工中")
    --self.trackMap.curIndex = 1
end



return TrackMapReaderInfinity

